using System.Collections.Immutable;
using System.Globalization;

namespace Delta.ECS.Generators;

/// <summary>Raw-string templates for validated demand-driven iteration shapes.</summary>
internal static partial class DemandDrivenForEachTemplates
{

    private const uint FnvOffsetBasis = 2_166_136_261u;
    private const uint FnvPrime = 16_777_619u;

    private const string InterceptorSourceHeader = """
        // <auto-generated />
        #nullable enable
        #pragma warning disable CS0436 // Demand-generated callback contracts can also arrive through a referenced consumer assembly.

        """;
    internal static string RenderGenericFunctorKernel(IterationModel shape, string methodName)
    {
        string componentParameters = shape.Api.Signature.ComponentIdParameters("componentId");
        if (componentParameters.Length > 0)
        {
            componentParameters = ", " + componentParameters;
        }

        return GeneratorTemplates.JoinNonEmpty(new[]
        {
            shape.Parallel || shape.HasEntityTarget ? RenderParallelInvoker(shape) : string.Empty,
            shape.Parallel
                ? RenderClosedParallelMethod(shape, methodName, componentParameters)
                : RenderClosedDenseMethod(shape, methodName, componentParameters),
        });
    }
    internal static string Render(IterationRenderModel model)
    {
        IterationModel shape = model.Shape;
        string? contracts = model.RenderContracts && !shape.OrderedQueryReceiver && !shape.IsFunctor && shape.ComponentModels.Length > 0
            ? RenderContracts(model)
            : null;
        string? invoker = shape.Parallel || shape.HasEntityTarget
            ? RenderParallelInvoker(shape)
            : null;
        string extension = GeneratorTemplates.ExtensionTemplate(
            $"DemandForEachExtensions_{GeneratorSupport.StableName(shape.Key)}",
            shape.IsFunctor,
            RenderExtensionsBody(model));
        string? componentSetKey = !shape.OrderedQueryReceiver && !shape.HasQuery && !shape.Api.Signature.HasExplicitIds
            ? GeneratorTemplates.PrimaryComponentSetKeyDeclaration(shape.Api.Selector.Arity)
            : null;
        string[] members = new[] { componentSetKey, contracts, invoker, extension }.OfType<string>().ToArray();
        ImmutableArray<string> usings = ImmutableArray.Create("using System;")
            .AddRange(GeneratorSupport.EcsNamespaceUsings(shape.Namespace));
        return GeneratorTemplates.FileTemplate(new GeneratedFileModel(
            shape.Namespace,
            usings,
            members.ToImmutableArray()));
    }

    internal static bool SupportsDirectExecution(InterceptionSite site) =>
        CanInlineInterceptedLambda(site)
        && !site.Shape.HasContext
        && !site.Shape.HasEntityTarget
        && !site.Shape.Parallel
        && !site.Shape.Api.Signature.HasExplicitIds;

    internal static string RenderInterceptorSource(InterceptionSite site)
    {
        IterationModel shape = site.IterationModel;
        string usings = GeneratorTemplates.InterceptorUsings(site.Usings);
        string execution = shape.HasEntityTarget || shape.Parallel
            ? GeneratorTemplates.JoinNonEmpty([
                RenderInterceptedParallelInvoker(shape, site),
                RenderInterceptedParallelClosedMethod(shape, site)
            ])
            : RenderInterceptedClosedMethod(shape, site);
        string source = GeneratorTemplates.JoinNonEmpty([
            usings,
            $$"""
            namespace Delta.ECS.Generated
            {

            file static class ForEachInterceptor_{{site.Id}}
            {
            """,
            CanInlineInterceptedLambda(site) ? string.Empty : RenderInterceptedCallback(site),
            execution,
            RenderInterceptor(shape, site)
        ]);
        return GeneratorTemplates.InterceptorTemplate(
            InterceptorSourceHeader,
            source + "}\n",
            GeneratorTemplates.InterceptorSourceFooter);
    }

    private static string RenderContracts(IterationRenderModel model)
    {
        IterationModel shape = model.Shape;
        SignatureProjection slots = shape.Api.Signature;
        string generic = slots.GenericList();
        string parameters = slots.ComponentParameters();
        string suffix = IsAllWrite(shape.ComponentModels) ? string.Empty : "_" + shape.Pattern;
        string entityParameter = model.SupportsScoped ? "scoped EntityRef entity" : "EntityRef entity";
        IEnumerable<string> contracts = new[]
        {
            AppendContract("ForEachAction" + suffix, generic, parameters),
            AppendContract("ForEachEntityAction" + suffix, generic, SignatureProjection.JoinParameters(entityParameter, parameters)),
        }.Concat(model.SupportedContextModes
            .SelectMany(mode =>
            {
                string context = SignatureProjection.ContextParameter(mode, "TContext", "context");
                string contextGeneric = SignatureProjection.JoinGeneric("TContext", generic);
                string modeSuffix = ContextDelegateSuffix(mode);
                return new[]
                {
                    AppendContract("ForEachContextAction" + modeSuffix + suffix, contextGeneric, SignatureProjection.JoinParameters(context, parameters)),
                    AppendContract(
                        "ForEachContextEntityAction" + modeSuffix + suffix,
                        contextGeneric,
                        SignatureProjection.JoinParameters(SignatureProjection.JoinParameters(context, entityParameter), parameters)),
                };
            }));
        return string.Join("\n", contracts) + "\n";
    }

    private static string AppendContract(string name, string generic, string parameters) => $"public delegate void {SignatureProjection.TypeWithArguments(name, generic)}({parameters});";

    private static string RenderParallelInvoker(IterationModel shape)
    {
        SignatureProjection slots = shape.Api.Signature;
        string generic = slots.HasGenericSelectors ? slots.GenericList() : string.Empty;
        string stateGeneric = StateGeneric(shape, generic);
        string name = ParallelInvokerName(shape);
        string actionType = ActionType(shape);
        string rows = GeneratorTemplates.JoinNonEmpty(GeneratorTemplates.Indexed(shape.ComponentModels.Length, index =>
            {
                string componentType = shape.ComponentModels[index].TypeName;
                return $"ref {componentType} row{index} = ref slots.GetGeneratedReadReference<{componentType}>(_access{index});";
            }));
        string entityBase = shape.HasEntity
            ? "GeneratedEntityRefView entityRefView = default;\n        EntityRef entity = slots.CreateEntityRef(ref entityRefView);\n        slots.BindEntityRef(ref entityRefView);"
            : string.Empty;
        string invocation = AppendClosedInvocation(shape, "_action", "_functor", "_context", "row", "entity");
        string loopBody;
        string visitHelpers = string.Empty;
        if (shape.HasEntity)
        {
            var loopLines = new List<string>
            {
                "for (int index = 0; index < count; index++)",
                "{",
                "    slots.SetEntityRefSlot(ref entityRefView, slots.GetGeneratedSlotIndex(index));"
            };
            loopLines.AddRange(GeneratorTemplates.Indexed(shape.ComponentModels.Length, index =>
                $"    ref {shape.ComponentModels[index].TypeName} current{index} = ref global::System.Runtime.CompilerServices.Unsafe.Add(ref row{index}, slots.GetGeneratedRowOffset(index));"));
            loopLines.Add("    " + AppendClosedInvocation(
                shape,
                "_action",
                "_functor",
                "_context",
                "current",
                "entity",
                index => $"current{index}") + ";");
            loopLines.Add("}");
            loopBody = AppendParallelTagSelectionLoop(
                shape,
                loopLines,
                "_context",
                "_action",
                "_functor",
                "row");
        }
        else
        {
            var cursors = new List<(string TypeName, string Name)>();

            for (int index = 0; index < shape.ComponentModels.Length; index++)
            {
                cursors.Add((shape.ComponentModels[index].TypeName, $"row{index}"));
            }

            (string visitRefParameters, string visitRefArguments) = BuildVisitRefLists(cursors);
            var leading = new List<string>();
            var leadingArgs = new List<string>();
            if (shape.HasContext)
            {
                leading.Add(SignatureProjection.ContextParameter(shape.ContextMode, ContextType(shape), "context"));
                leadingArgs.Add(SignatureProjection.ContextArgument(shape.ContextMode, "_context"));
            }

            if (shape.IsFunctor)
            {
                leading.Add(SignatureProjection.ContextParameter(shape.FunctorPassMode, shape.FunctorType!, "functor"));
                leadingArgs.Add(SignatureProjection.ContextArgument(shape.FunctorPassMode, "_functor"));
            }
            else
            {
                leading.Add($"{actionType} action");
                leadingArgs.Add("_action");
            }

            var loopLines = new List<string>();
            var visitMethods = new List<string>();
            AppendUnrolledDenseSlotLoop(
                loopLines,
                visitMethods,
                "                    ",
                "        ",
                "count",
                visitRefParameters,
                visitRefArguments,
                (stepLines, stepIndent, offset, pin) =>
                {
                    string invocation = AppendClosedInvocation(
                        shape,
                        "action",
                        "functor",
                        "context",
                        "row",
                        string.Empty,
                        index => AtOffset(pin("row" + index), offset));
                    stepLines.Add($"{stepIndent}{invocation};");
                },
                (advanceLines, advanceIndent, advance) =>
                {
                    advanceLines.AddRange(GeneratorTemplates.Indexed(shape.ComponentModels.Length, index =>
                        $"{advanceIndent}row{index} = ref {UnsafeAdd($"row{index}", advance)};"));
                },
                visitLeadingParameters: string.Join(", ", leading),
                visitLeadingArguments: string.Join(", ", leadingArgs));
            loopBody = string.Join("\n", loopLines);
            visitHelpers = string.Join("\n", visitMethods);
            loopBody = AppendParallelTagSelectionLoop(
                shape,
                loopLines,
                "_context",
                "_action",
                "_functor",
                "row");
        }

        return $$"""
            internal struct {{name}}{{stateGeneric}} : IGeneratedParallelInvoker
            {
            {{AppendInvokerFields(shape, actionType)}}
            {{AppendInvokerConstructor(shape, name, actionType)}}

                public bool RequiresSingleThread => {{(shape.ContextMode == ContextModeKind.Ref ? "true" : "false")}};

                [global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
                public void Invoke(ref GeneratedQuerySlots slots)
                {
            {{rows}}
            {{entityBase}}
                    int count = slots.Count;
            {{loopBody}}
                }
            {{visitHelpers}}
            {{AppendInvokerProperties(shape)}}
            }
            """;
    }

    private static string AppendInvokerFields(IterationModel shape, string actionType)
    {
        string context = shape.HasContext
            ? $"private {ContextType(shape)} _context;"
            : string.Empty;
        string callback = shape.IsFunctor
            ? $"private {shape.FunctorType} _functor;"
            : $"private readonly {actionType} _action;";
        return GeneratorTemplates.JoinNonEmpty(new[] { context, callback }
            .Concat(GeneratorTemplates.Indexed(shape.ComponentModels.Length,
                index => $"private readonly int _access{index};")));
    }

    private static string AppendInvokerConstructor(IterationModel shape, string name, string actionType)
    {
        string[] parameters = new[]
            {
                shape.HasContext ? $"{ContextType(shape)} context" : string.Empty,
                shape.IsFunctor ? $"{shape.FunctorType} functor" : $"{actionType} action",
                shape.Api.Signature.AccessParameters(tokens: true)
            }
            .Where(static parameter => parameter.Length != 0).ToArray();

        string[] assignments = new[]
            {
                shape.HasContext ? "_context = context;" : string.Empty,
                shape.IsFunctor ? "_functor = functor;" : "_action = action;"
            }
            .Concat(GeneratorTemplates.Indexed(shape.ComponentModels.Length, index =>
                $"_access{index} = GeneratedForEachRuntime.Get{(shape.ComponentModels[index].IsWrite ? "Write" : "Read")}QueryComponentIndex(access{index});"))
            .Where(static assignment => assignment.Length != 0).ToArray();

        return $$"""
                internal {{ConstructorName(name)}}({{string.Join(", ", parameters)}})
                {
            {{GeneratorTemplates.JoinNonEmpty(assignments)}}
                }
            """;
    }

    private static string AppendInvokerProperties(IterationModel shape) => GeneratorTemplates.JoinNonEmpty([
            shape.HasContext ? $"internal {ContextType(shape)} Context => _context;" : string.Empty,
            shape.IsFunctor ? $"internal {shape.FunctorType} Functor => _functor;" : string.Empty
        ]);

    private static string RenderClosedParallelMethod(IterationModel shape, string methodName, string componentParameters)
    {
        SignatureProjection slots = shape.Api.Signature;
        string generic = slots.HasGenericSelectors ? slots.GenericList() : string.Empty;
        string genericPrefix = StateGeneric(shape, generic);
        string contextParameter = shape.HasContext
            ? $", {SignatureProjection.ContextParameter(shape.ContextMode, ContextType(shape), "context")}"
            : string.Empty;
        string callbackParameter = shape.IsFunctor
            ? ", " + SignatureProjection.ContextParameter(shape.FunctorPassMode, shape.FunctorType!, "functor")
            : $", {ActionType(shape)} action";
        string invokerType = $"{ParallelInvokerName(shape)}{StateGeneric(shape, generic)}";
        string target = shape.HasEntityTarget
            ? ", global::System.ReadOnlySpan<Entity> entities, in Query query"
            : ", in Query query";
        string arguments = string.Join(", ", new[]
        {
            shape.HasContext ? "context" : null,
            shape.IsFunctor ? "functor" : "action",
            slots.AccessArguments(),
        }.Where(static value => !string.IsNullOrEmpty(value)));
        string execute = shape.HasEntityTarget
            ? "GeneratedForEachRuntime.ExecuteEntityListParallel(world, in query, entities, ref invoker, "
            : "GeneratedForEachRuntime.ExecuteParallelDense(world, in query, ref invoker, ";
        string body = $"""
                {(slots.HasDynamicIds ? $"GeneratedForEachRuntime.ValidateComponentIdCount(componentIds, {slots.Arity});" : string.Empty)}
                {GeneratorTemplates.Indent(AccessSetup(shape), "    ")}
                var invoker = new {invokerType}({arguments});
                {execute}{AppendParallelWriteIndices(shape)}, workerCount);
                {(shape is { HasContext: true, ContextMode: ContextModeKind.Ref } ? "context = invoker.Context;" : string.Empty)}
                {(shape is { IsFunctor: true, FunctorPassMode: ContextModeKind.Ref } ? "functor = invoker.Functor;" : string.Empty)}
            """;
        string signature = $"private static void {methodName}{genericPrefix}(World world{target}{componentParameters}{contextParameter}{callbackParameter}, int workerCount)";
        return GeneratorTemplates.Indent(GeneratorTemplates.RenderBlock(
            $"""
                [global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
                {signature}
                """.Trim(),
            body), "    ");
    }

    private static string AppendParallelWriteIndices(IterationModel shape)
    {
        if (!shape.ComponentModels.Any(static component => component.IsWrite))
        {
            return "global::System.ReadOnlySpan<int>.Empty";
        }

        string indices = string.Join(", ", GeneratorTemplates.WriteIndices(shape.ComponentModels)
            .Select(index => $"global::Delta.ECS.GeneratedForEachRuntime.GetWriteQueryComponentIndex(access{index})"));
        return $$"""stackalloc int[] { {{indices}} }""";
    }

    private static int StableProfileMethodId(string methodName)
    {
        uint hash = FnvOffsetBasis;
        foreach (char character in methodName)
        {
            hash ^= character;
            hash *= FnvPrime;
        }

        return (int)(hash & 0x7FFF_FFFF);
    }

    private static string AppendClosedInvocation(
        IterationModel shape,
        string actionName,
        string functorName,
        string contextName,
        string componentPrefix,
        string entityExpression,
        Func<int, string>? componentExpression = null)
    {
        var invocationArguments = new List<string>();
        if (shape.HasContext)
        {
            invocationArguments.Add(SignatureProjection.ContextArgument(shape.ContextMode, contextName));
        }

        if (shape.HasEntity)
        {
            invocationArguments.Add(entityExpression);
        }

        SignatureProjection slots = shape.Api.Signature;
        if (componentExpression is null)
        {
            string componentArguments = slots.ComponentArguments(componentPrefix);
            if (componentArguments.Length != 0)
            {
                invocationArguments.Add(componentArguments);
            }
        }
        else
        {
            for (int index = 0; index < slots.Arity; index++)
            {
                invocationArguments.Add(slots.ComponentArgument(index, componentExpression(index)));
            }
        }

        string invocation = shape.IsFunctor ? $"{functorName}.Invoke" : actionName;
        return $"{invocation}({string.Join(", ", invocationArguments)})";
    }

    private static string UnsafeAdd(string refExpression, string offsetExpression) => $"global::System.Runtime.CompilerServices.Unsafe.Add(ref {refExpression}, {offsetExpression})";

    private static string UnsafeAdd(string refExpression, int offset) => UnsafeAdd(refExpression, offset.ToString(CultureInfo.InvariantCulture));

    private static string AtOffset(string refExpression, int offset) => offset == 0 ? refExpression : UnsafeAdd(refExpression, offset);

    private static (string Parameters, string Arguments) BuildVisitRefLists(
        IReadOnlyList<(string TypeName, string Name)> cursors)
    {
        if (cursors.Count == 0)
        {
            return (string.Empty, string.Empty);
        }

        return (
            string.Join(", ", cursors.Select(static cursor => $"ref {cursor.TypeName} {cursor.Name}")),
            string.Join(", ", cursors.Select(static cursor => $"ref {cursor.Name}")));
    }

    /// <summary>
    /// Emits the dense unroll loop into <paramref name="loopLines"/> and private static
    /// VisitStep/Visit4 helpers into <paramref name="visitMethods"/> (constant offsets).
    /// Fast path peels on <c>(count &amp; ~3) != 0</c> (tst-friendly). Cursor refs are
    /// pinned into locals <c>b0..bn</c> for the Visit4 do-while so the JIT keeps stable
    /// base registers; locals advance by 4 at the end of each iteration and write back
    /// into the original cursors for the remainder. Remaining elements use a scalar
    /// <c>while</c> loop. Visit4 calls the action with direct <c>Unsafe.Add</c> offsets —
    /// no temporary slot refs inside Visit*.
    /// </summary>
    private static void AppendUnrolledDenseSlotLoop(
        List<string> loopLines,
        List<string> visitMethods,
        string loopIndent,
        string visitMethodIndent,
        string countName,
        string visitRefParameters,
        string visitRefArguments,
        Action<List<string>, string, int, Func<string, string>> emitStep,
        Action<List<string>, string, int> emitAdvance,
        string visitLeadingParameters = "",
        string visitLeadingArguments = "",
        string visitMethodGenerics = "",
        bool isolateSteps = false)
    {
        string visitParameters = string.IsNullOrEmpty(visitLeadingParameters)
            ? visitRefParameters
            : string.IsNullOrEmpty(visitRefParameters)
                ? visitLeadingParameters
                : visitLeadingParameters + ", " + visitRefParameters;

        string[] cursorNames = string.IsNullOrEmpty(visitRefArguments)
            ? []
            : visitRefArguments.Split([", "], StringSplitOptions.None).Select(static part => part.StartsWith("ref ", StringComparison.Ordinal) ? part.Substring(4) : part).ToArray();

        string ShiftedCursorArguments(string[] names, int shift)
        {
            if (names.Length == 0)
            {
                return string.Empty;
            }

            if (shift == 0)
            {
                return string.Join(", ", names.Select(static name => $"ref {name}"));
            }

            return string.Join(", ", names.Select(name => "ref " + UnsafeAdd(name, shift)));
        }

        string Call(string name, string[] names, int cursorShift = 0)
        {
            string cursors = ShiftedCursorArguments(names, cursorShift);
            string args = string.IsNullOrEmpty(visitLeadingArguments)
                ? cursors
                : string.IsNullOrEmpty(cursors)
                    ? visitLeadingArguments
                    : visitLeadingArguments + ", " + cursors;
            return $"{name}({args})";
        }

        Func<string, string> pinIdentity = static name => name;

        void EmitVisitMethod(int times, string functionName)
        {
            visitMethods.Add($"{visitMethodIndent}[global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]");
            visitMethods.Add($"{visitMethodIndent}private static void {functionName}{visitMethodGenerics}({visitParameters})");
            visitMethods.Add($"{visitMethodIndent}{{");
            for (int step = 0; step < times; step++)
            {
                if (isolateSteps)
                {
                    visitMethods.Add($"{visitMethodIndent}    {{");
                    emitStep(visitMethods, visitMethodIndent + "        ", step, pinIdentity);
                    visitMethods.Add($"{visitMethodIndent}    }}");
                }
                else
                {
                    emitStep(visitMethods, visitMethodIndent + "    ", step, pinIdentity);
                }
            }

            visitMethods.Add($"{visitMethodIndent}}}");
            visitMethods.Add(string.Empty);
        }

        EmitVisitMethod(1, "VisitStep");
        EmitVisitMethod(4, "Visit4");

        loopLines.Add($"{loopIndent}#pragma warning disable CS8619 // Unsafe.Add returns a maybe-null ref for unconstrained T; this loop only advances the reference.");
        loopLines.Add($"{loopIndent}if (({countName} & ~3) != 0)");
        loopLines.Add($"{loopIndent}{{");
        loopLines.Add($"{loopIndent}    int loops = {countName} >> 2;");
        string[] hotNames = cursorNames;
        if (cursorNames.Length > 0)
        {
            hotNames = new string[cursorNames.Length];
            for (int index = 0; index < cursorNames.Length; index++)
            {
                string local = "b" + index.ToString(CultureInfo.InvariantCulture);
                hotNames[index] = local;
                loopLines.Add($"{loopIndent}    ref var {local} = ref {cursorNames[index]};");
            }
        }

        loopLines.Add($"{loopIndent}    do");
        loopLines.Add($"{loopIndent}    {{");
        loopLines.Add($"{loopIndent}        {Call("Visit4", hotNames)};");
        for (int index = 0; index < hotNames.Length; index++)
        {
            loopLines.Add($"{loopIndent}        {hotNames[index]} = ref {UnsafeAdd(hotNames[index], 4)};");
        }

        if (hotNames.Length == 0)
        {
            emitAdvance(loopLines, loopIndent + "        ", 4);
        }

        loopLines.Add($"{loopIndent}        loops--;");
        loopLines.Add($"{loopIndent}    }} while (loops != 0);");
        if (cursorNames.Length > 0)
        {
            for (int index = 0; index < cursorNames.Length; index++)
            {
                loopLines.Add($"{loopIndent}    {cursorNames[index]} = ref {hotNames[index]};");
            }
        }

        loopLines.Add($"{loopIndent}}}");
        loopLines.Add($"{loopIndent}#pragma warning restore CS8619");
        loopLines.Add($"{loopIndent}int remaining = {countName} & 3;");
        loopLines.Add($"{loopIndent}while (remaining != 0)");
        loopLines.Add($"{loopIndent}{{");
        loopLines.Add($"{loopIndent}    {Call("VisitStep", cursorNames)};");
        emitAdvance(loopLines, loopIndent + "    ", 1);
        loopLines.Add($"{loopIndent}    remaining--;");
        loopLines.Add($"{loopIndent}}}");
    }

    private static string RenderExtensionsBody(IterationRenderModel model)
    {
        IterationModel shape = model.Shape;
        if (shape.OrderedQueryReceiver)
        {
            string orderedClosedMethodName = "ExecuteClosed_" + GeneratorSupport.StableName(shape.Key);
            string orderedClosedMethod = RenderClosedDenseMethod(shape, orderedClosedMethodName, shape.Api.Signature.HasExplicitIds
                ? ", " + shape.Api.Signature.ComponentIdParameters("componentId")
                : string.Empty);
            return orderedClosedMethod + "\n" + RenderOrderedExtensionsBody(shape);
        }

        SignatureProjection slots = shape.Api.Signature;
        string className = "DemandForEachExtensions_" + GeneratorSupport.StableName(shape.Key);
        string generic = slots.HasGenericSelectors ? slots.GenericList() : string.Empty;
        string ids = slots.HasExplicitIds ? slots.ComponentIdParameters("componentId") : string.Empty;
        string stateGeneric = StateGeneric(shape, generic);
        string callback = ActionType(shape);
        bool cachePreparedAccess = CachesPreparedAccess(shape);
        string componentParameters = slots.HasExplicitIds && !cachePreparedAccess ? ", " + slots.ComponentIdParameters("componentId") : string.Empty;
        string prefix = shape.HasEntityTarget
            ? "this World world, global::System.ReadOnlySpan<Entity> entities"
            : "this World world";
        string query = shape.HasQuery ? ", in Query query" : string.Empty;
        string contextParameter = shape.HasContext
            ? ", " + SignatureProjection.ContextParameter(shape.ContextMode, ContextType(shape), "context")
            : string.Empty;
        string closedMethodName = "ExecuteClosed_" + GeneratorSupport.StableName(shape.Key);
        string closed = shape.Parallel
            ? RenderClosedParallelMethod(shape, closedMethodName, componentParameters)
            : RenderClosedDenseMethod(shape, closedMethodName, componentParameters, cachePreparedAccess: cachePreparedAccess);
        string extension = RenderExtensionMethod(
            shape,
            prefix,
            query,
            contextParameter,
            ids,
            callback,
            stateGeneric,
            className,
            model.Profiling,
            closedMethodName);
        string operationInvoker = RenderOperationInvoker(
            shape,
            closedMethodName,
            model.Profiling,
            StableProfileMethodId(className + "." + shape.MethodName),
            model.HasInterceptedExecution);
        string executionDelegate = model.HasInterceptedExecution
            ? RenderInterceptedExecutionDelegate(shape)
            : string.Empty;
        return GeneratorTemplates.JoinNonEmpty([closed, executionDelegate, operationInvoker, extension]);
    }

    private static string RenderInterceptedExecutionDelegate(IterationModel shape) =>
        $"internal delegate void {InterceptedExecutionName(shape)}(global::Delta.ECS.World world, in global::Delta.ECS.Query query);";

    private static string InterceptedExecutionName(IterationModel shape) =>
        "InterceptedExecution_" + GeneratorSupport.StableName(shape.Key);

    private static string RenderOrderedExtensionsBody(IterationModel shape)
    {
        SignatureProjection slots = shape.Api.Signature;
        string generic = slots.HasGenericSelectors ? slots.GenericList() : string.Empty;
        string stateGeneric = StateGeneric(shape, generic);
        string whereGeneric = shape.OrderedWhereSource is { } whereSource
            ? GeneratedWhereTemplates.ViewMethodTypeParameters(whereSource)
            : string.Empty;
        string methodGeneric = SignatureProjection.TypeArguments(
            SignatureProjection.JoinGeneric(stateGeneric.Trim('<', '>'), whereGeneric));
        string receiverType = shape.OrderedWhereSource is { } orderedWhereSource
            ? GeneratedWhereTemplates.OrderedViewTypeName(orderedWhereSource)
                + GeneratedWhereTemplates.ViewMethodTypeArguments(orderedWhereSource)
            : "OrderedQuery";
        string ids = slots.HasExplicitIds ? slots.ComponentIdParameters("componentId") : string.Empty;
        string context = shape.HasContext
            ? SignatureProjection.ContextParameter(shape.ContextMode, ContextType(shape), "context")
            : string.Empty;
        string callback = shape.IsFunctor
            ? SignatureProjection.ContextParameter(shape.FunctorPassMode, shape.FunctorType!, "functor")
            : ActionType(shape) + " action";
        var parameters = new List<string> { "this " + receiverType + " orderedQuery" };
        if (ids.Length != 0)
        {
            parameters.Add(ids);
        }

        if (context.Length != 0)
        {
            parameters.Add(context);
        }

        parameters.Add(callback);
        string visibility = shape.IsFunctor || shape.ImplicitComponents ? "internal" : "public";
        string signature = $"{visibility} static {OperationType(shape)} {shape.MethodName}{methodGeneric}({string.Join(", ", parameters)})";
        string closedMethod = "ExecuteClosed_" + GeneratorSupport.StableName(shape.Key);
        bool mutableContext = shape.HasContext && shape.ContextMode == ContextModeKind.Ref;
        var setup = new List<string> { "var operationOrderedQuery = orderedQuery;" };
        if (slots.HasDynamicIds)
        {
            setup.Add("global::Delta.ECS.ComponentId[] operationComponentIds = componentIds.ToArray();");
        }

        var invokerArguments = new List<string> { "operationOrderedQuery" };
        if (slots.HasDynamicIds)
        {
            invokerArguments.Add("operationComponentIds");
        }
        else if (slots.HasExplicitIds)
        {
            invokerArguments.Add(slots.ComponentIdArguments("componentId"));
        }

        if (shape.HasContext && !mutableContext)
        {
            invokerArguments.Add("context");
        }

        if (!shape.IsFunctor)
        {
            invokerArguments.Add("action");
        }

        if (shape.Parallel)
        {
            invokerArguments.Add("workerCount");
        }

        string invoker = $"new {OperationInvokerType(shape)}({string.Join(", ", invokerArguments)})";
        string operation = EcsOperationTemplates.CreationExpression(
            OperationType(shape),
            invoker,
            mutableContext ? ContextType(shape) : null,
            shape.IsFunctor ? shape.FunctorType : null);
        setup.Add($"return {operation};");
        string body = GeneratorTemplates.RenderBlock(string.Empty, string.Join("\n", setup));
        string operationInvoker = RenderOrderedOperationInvoker(shape, closedMethod);
        string extension = GeneratorTemplates.Indent(
            RenderMethod(
                GeneratorTemplates.Documentation(shape.Api),
                signature,
                body,
                null),
            "    ");
        return operationInvoker + "\n" + extension;
    }

    private static string RenderOrderedOperationInvoker(IterationModel shape, string closedMethodName)
    {
        string genericParameters = OperationInvokerGenericParameters(shape);
        string generic = shape.Api.Signature.HasGenericSelectors ? shape.Api.Signature.GenericList() : string.Empty;
        string stateGeneric = StateGeneric(shape, generic);
        string receiverType = shape.OrderedWhereSource is { } source
            ? GeneratedWhereTemplates.OrderedViewTypeName(source) + GeneratedWhereTemplates.ViewMethodTypeArguments(source)
            : "global::Delta.ECS.OrderedQuery";
        bool mutableContext = shape.HasContext && shape.ContextMode == ContextModeKind.Ref;
        string? contextType = mutableContext ? ContextType(shape) : null;
        string? functorType = shape.IsFunctor ? shape.FunctorType : null;
        string interfaceType = EcsOperationTemplates.InvokerInterface(contextType, functorType);
        string visibility = shape.IsFunctor || shape.ImplicitComponents ? "internal" : "public";
        var fields = new List<string> { $"private readonly {receiverType} _orderedQuery;" };
        var constructorParameters = new List<string> { receiverType + " orderedQuery" };
        var assignments = new List<string> { "_orderedQuery = orderedQuery;" };
        AppendOperationInvokerMembers(shape, fields, constructorParameters, assignments);
        var body = new List<string>
        {
            "var operationOrderedQuery = _orderedQuery;",
            "global::System.ReadOnlySpan<global::Delta.ECS.Entity> __entities = default;",
            "global::Delta.ECS.Query __query = operationOrderedQuery.SourceQuery;",
            shape.Api.Signature.ComponentIdLocals("operationComponentIds"),
            shape.HasContext && shape.ContextMode != ContextModeKind.Ref ? $"{ContextType(shape)} operationContextCopy = _context;" : string.Empty,
            shape.IsFunctor ? string.Empty : $"{ActionType(shape)} action = _action;",
            shape.Parallel ? "int workerCount = _workerCount;" : string.Empty,
            "try",
            "{",
            "    __entities = operationOrderedQuery.BeginForEach();",
            $"    {closedMethodName}{stateGeneric}({string.Join(", ", new[] { "operationOrderedQuery.World", "__entities", "in __query" }.Concat(shape.Api.Signature.HasExplicitIds ? [shape.Api.Signature.HasDynamicIds ? "operationComponentIds" : shape.Api.Signature.ComponentIdArguments("componentId")] : Array.Empty<string>()).Concat(shape.HasContext ? [SignatureProjection.ContextArgument(shape.ContextMode, shape.ContextMode == ContextModeKind.Ref ? "context" : "operationContextCopy")] : Array.Empty<string>()).Append(shape.IsFunctor ? SignatureProjection.ContextArgument(shape.FunctorPassMode, "functor") : "action"))});",
            "}",
            "finally",
            "{",
            shape.OrderedWhereSource is null ? "    operationOrderedQuery.EndForEach();" : "    operationOrderedQuery.Ordering.EndForEach();",
            "}"
        };
        string methodDeclaration = EcsOperationTemplates.InvokeMethod(interfaceType, contextType, functorType);
        string operationInvoker = $$"""
            [global::System.ComponentModel.EditorBrowsable(global::System.ComponentModel.EditorBrowsableState.Never)]
            {{visibility}} struct {{OperationInvokerName(shape)}}{{genericParameters}} : {{interfaceType}}
            {
            {{GeneratorTemplates.JoinNonEmpty(fields)}}

                internal {{OperationInvokerName(shape)}}({{string.Join(", ", constructorParameters.Where(static parameter => parameter.Length != 0))}})
                {
            {{GeneratorTemplates.Indent(GeneratorTemplates.JoinNonEmpty(assignments), "        ")}}
                }

            {{GeneratorTemplates.RenderBlock(methodDeclaration, string.Join("\n", body))}}
            }
            """;
        return operationInvoker;
    }

    private static string RenderInterceptedCallback(InterceptionSite site)
    {
        IterationModel shape = site.IterationModel;
        SignatureProjection slots = shape.Api.Signature;
        string callbackName = "InvokeInterceptedCallback_" + site.Id;
        string[] parameters = InterceptedParameterNames(site);
        int parameterIndex = 0;
        var declarations = new List<string>();
        if (shape.HasContext)
        {
            declarations.Add(SignatureProjection.ContextParameter(shape.ContextMode, InterceptedContextType(shape), parameters[parameterIndex++]));
        }
        if (shape.HasEntity)
        {
            declarations.Add("global::Delta.ECS.EntityRef " + parameters[parameterIndex++]);
        }
        declarations.AddRange(Enumerable.Range(0, slots.Arity).Select(index =>
            slots.ComponentParameter(index, shape.ComponentModels[index].ResolvedTypeName, parameters[parameterIndex + index])));
        string body = site.Binding.LambdaBody is not null
            ? AppendInterceptedLambdaBody(site, "    ")
            : AppendCallbackInvocation(shape, site.Binding.MethodGroupTarget!, parameters, "    ");
        string declaration = $"""
            [global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
            private static void {callbackName}({string.Join(", ", declarations)})
            """.Trim();
        return GeneratorTemplates.RenderBlock(declaration, body);
    }

    private static bool CanInlineInterceptedLambda(InterceptionSite site) =>
        site.Binding.LambdaBody is not null && site.Binding.CanInline;

    private static string GeneratedLocalName(InterceptionSite site, string prefix, int ordinal)
    {
        string baseName = ordinal == 0
            ? prefix
            : prefix + ordinal.ToString(CultureInfo.InvariantCulture);
        if (site.Binding.LambdaIdentifiers.IsEmpty
            && !site.Binding.LambdaParameterNames.Contains(baseName, StringComparer.Ordinal))
        {
            return baseName;
        }

        string candidate = baseName;
        int suffix = 0;
        while (site.Binding.LambdaIdentifiers.Contains(candidate)
            || site.Binding.LambdaParameterNames.Contains(candidate, StringComparer.Ordinal))
        {
            candidate = baseName + "_" + ++suffix;
        }

        return candidate;
    }

    private static string AppendInterceptedLambdaBody(InterceptionSite site, string indent)
    {
        if (site.Binding.LambdaBodyIsBlock)
        {
            return GeneratorTemplates.Indent(site.Binding.LambdaBody!, indent);
        }
        return site.Binding.LambdaBody is null ? string.Empty : indent + site.Binding.LambdaBody + ";";
    }

    private static string AppendCallbackBody(
        IterationModel shape,
        InterceptionSite site,
        bool inlineLambda,
        string callbackName,
        string[] parameters,
        string indent)
        => inlineLambda
            ? AppendInterceptedLambdaBody(site, indent)
            : AppendCallbackInvocation(shape, callbackName, parameters, indent);

    private static void AppendChunkFilterBranch(List<string> lines, Action<bool> appendChunkLoop)
    {
        lines.Add("    if (execution.HasTagFilters)");
        lines.Add("    {");
        appendChunkLoop(true);
        lines.Add("    }");
        lines.Add("    else");
        lines.Add("    {");
        appendChunkLoop(false);
        lines.Add("    }");
    }

    private static void PrependDenseLoopCount(List<string> denseLoopLines, bool hasEntity, string countName)
    {
        if (!hasEntity)
        {
            return;
        }

        denseLoopLines.Insert(0, $"int {countName} = slots.Count;");
    }

    private static string RenderInterceptedClosedMethod(IterationModel shape, InterceptionSite site)
    {
        IterationModel closedShape = new(
            shape.RegistrationBinding,
            shape.HasEntity,
            shape.HasContext,
            isFunctor: true,
            shape.Pattern,
            shape.Components,
            functorType: null,
            contextType: shape.ContextType,
            contextMode: shape.ContextMode,
            methodName: shape.MethodName,
            typeBinding: TypeBindingKind.CallbackInferred);
        string[] parameters = InterceptedParameterNames(site);
        string methodName = "ExecuteInterceptedClosed_" + site.Id;
        string callbackName = "InvokeInterceptedCallback_" + site.Id;
        string countName = GeneratedLocalName(site, "count", 0);
        string[] rowNames = GeneratorTemplates.Indexed(closedShape.ComponentModels.Length, index => GeneratedLocalName(site, "row", index)).ToArray();
        SignatureProjection slots = closedShape.Api.Signature;
        bool inlineLambda = CanInlineInterceptedLambda(site);
        string contextParameterName = closedShape.HasContext
            ? closedShape.ContextMode == ContextModeKind.Ref
                ? GeneratedLocalName(site, "context", 0)
                : parameters[0]
            : "context";
        string componentParameters = slots.HasExplicitIds ? ", " + slots.ComponentIdParameters("componentId") : string.Empty;
        string contextParameter = closedShape.HasContext
            ? ", " + SignatureProjection.ContextParameter(closedShape.ContextMode, InterceptedContextType(closedShape), contextParameterName)
            : string.Empty;
        string signature = $"private static void {methodName}(global::Delta.ECS.World world, in global::Delta.ECS.Query query{componentParameters}{contextParameter})";
        var lines = new List<string>
        {
            "[global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]",
            signature,
            "{",
            "    GeneratedForEachRuntime.ValidateGeneratedWhere(world, in query);",
            slots.HasDynamicIds
                ? $"    GeneratedForEachRuntime.ValidateComponentIdCount(componentIds, {slots.Arity});"
                : string.Empty,
            GeneratorTemplates.Indent(AccessSetup(closedShape).TrimEnd(), "    "),
        };
        var interceptedVisitMethods = new List<string>();
        if (closedShape is { HasContext: true, ContextMode: ContextModeKind.Ref })
        {
            lines.Add($"    {InterceptedContextType(closedShape)} {parameters[0]} = {contextParameterName};");
        }
        lines.Add($"    using var execution = GeneratedForEachRuntime.{(closedShape.ComponentModels.Any(static component => component.IsWrite) ? "OpenWriteDense" : "OpenReadDense")}(world, in query);");
        lines.AddRange(SplitLines(AppendQueryComponentRoutes(closedShape, "    ")));
        lines.AddRange(SplitLines(AppendArchetypeWriteSetup(shape, "    ")));
        int entityParameterIndex = closedShape.HasContext ? 1 : 0;
        if (closedShape.HasEntity)
        {
            lines.Add("    global::Delta.ECS.GeneratedEntityRefView entityRefView = default;");
            lines.Add($"    global::Delta.ECS.EntityRef {parameters[entityParameterIndex]} = GeneratedForEachRuntime.CreateEntityRef(world, ref entityRefView);");
        }
        for (int index = 0; index < closedShape.ComponentModels.Length; index++)
        {
            string type = closedShape.Components[index];
            lines.Add($"    ref {type} {rowNames[index]} = ref global::System.Runtime.CompilerServices.Unsafe.NullRef<{type}>();");
        }

        var visitMethods = new List<string>();
        var denseLoopLines = new List<string>();
        if (closedShape.HasEntity)
        {
            denseLoopLines.Add("for (int index = 0; index < count; index++)");
            denseLoopLines.Add("{");
            denseLoopLines.Add("    slots.SetEntityRefSlot(ref entityRefView, slots.GetGeneratedSlotIndex(index));");
            if (inlineLambda)
            {
                for (int index = 0; index < closedShape.ComponentModels.Length; index++)
                {
                    denseLoopLines.Add($"    {(closedShape.ComponentModels[index].IsWrite ? "ref " : "ref readonly ")}{closedShape.ComponentModels[index].ResolvedTypeName} {parameters[entityParameterIndex + 1 + index]} = ref global::System.Runtime.CompilerServices.Unsafe.Add(ref {rowNames[index]}, slots.GetGeneratedRowOffset(index));");
                }

                denseLoopLines.Add(AppendInterceptedLambdaBody(site, "    "));
            }
            else
            {
                string[] callbackParameters = (string[])parameters.Clone();
                for (int index = 0; index < rowNames.Length; index++)
                {
                    callbackParameters[entityParameterIndex + 1 + index] = $"global::System.Runtime.CompilerServices.Unsafe.Add(ref {rowNames[index]}, slots.GetGeneratedRowOffset(index))";
                }

                denseLoopLines.Add(AppendCallbackInvocation(closedShape, callbackName, callbackParameters, "    "));
            }

            denseLoopLines.Add("}");
        }
        else
        {
            var cursors = new List<(string TypeName, string Name)>();
            for (int index = 0; index < closedShape.ComponentModels.Length; index++)
            {
                cursors.Add((closedShape.ComponentModels[index].ResolvedTypeName, rowNames[index]));
            }

            (string visitRefParameters, string visitRefArguments) = BuildVisitRefLists(cursors);
            var leading = new List<string>();
            var leadingArgs = new List<string>();
            if (closedShape.HasContext)
            {
                leading.Add(SignatureProjection.ContextParameter(
                    closedShape.ContextMode,
                    InterceptedContextType(closedShape),
                    parameters[0]));
                leadingArgs.Add(SignatureProjection.ContextArgument(closedShape.ContextMode, parameters[0]));
            }

            AppendUnrolledDenseSlotLoop(
                denseLoopLines,
                visitMethods,
                "        ",
                "    ",
                countName,
                visitRefParameters,
                visitRefArguments,
                (stepLines, stepIndent, offset, pin) =>
                {
                    if (inlineLambda)
                    {
                        for (int index = 0; index < closedShape.ComponentModels.Length; index++)
                        {
                            stepLines.Add($"{stepIndent}{(closedShape.ComponentModels[index].IsWrite ? "ref " : "ref readonly ")}{closedShape.ComponentModels[index].ResolvedTypeName} {parameters[entityParameterIndex + index]} = ref {AtOffset(pin(rowNames[index]), offset)};");
                        }

                        stepLines.Add(AppendInterceptedLambdaBody(site, stepIndent));
                    }
                    else
                    {
                        string[] callbackParameters = (string[])parameters.Clone();
                        int firstComponentParameter = closedShape.HasContext ? 1 : 0;
                        for (int index = 0; index < rowNames.Length; index++)
                        {
                            callbackParameters[firstComponentParameter + index] = AtOffset(pin(rowNames[index]), offset);
                        }

                        stepLines.Add(AppendCallbackInvocation(closedShape, callbackName, callbackParameters, stepIndent));
                    }
                },
                (advanceLines, advanceIndent, advance) =>
                {
                    advanceLines.AddRange(GeneratorTemplates.Indexed(closedShape.ComponentModels.Length,
                        index => $"{advanceIndent}{rowNames[index]} = ref {UnsafeAdd(rowNames[index], advance)};"));
                },
                visitLeadingParameters: string.Join(", ", leading),
                visitLeadingArguments: string.Join(", ", leadingArgs),
                isolateSteps: true);
        }

        void AppendChunkLoop(bool filterTagSlots)
        {
            lines.Add(closedShape.HasEntity
                ? "        while (execution.MoveNextTrusted(out var slots))"
                : $"        while (execution.MoveNextTrusted(out var componentRows, out int {countName}))");
            lines.Add("        {");

            if (closedShape.HasEntity)
            {
                lines.Add("            slots.BindEntityRef(ref entityRefView);");
            }

            for (int index = 0; index < closedShape.ComponentModels.Length; index++)
            {
                string type = closedShape.Components[index];
                lines.Add(closedShape.HasEntity
                    ? $"                {rowNames[index]} = ref GeneratedForEachRuntime.GetGeneratedArrayReference(slots.GetGeneratedArray<{type}>(access{index}));"
                    : $"                {rowNames[index]} = ref GeneratedForEachRuntime.GetGeneratedRow<{type}>(componentRows, route{index});");
            }
            if (filterTagSlots)
            {
                AppendInterceptedTagSelectionLoop(
                    lines,
                    closedShape,
                    site,
                    "execution.TryGetTagSlots(out var tagSlots)",
                    string.Empty,
                    callbackName,
                    parameters,
                    inlineLambda,
                    rowNames,
                    denseLoopLines);
            }
            else
            {
                lines.AddRange(denseLoopLines);
            }

            lines.Add("        }");
        }

        PrependDenseLoopCount(denseLoopLines, closedShape.HasEntity, countName);

        AppendChunkFilterBranch(lines, AppendChunkLoop);
        interceptedVisitMethods = visitMethods;
        if (closedShape is { HasContext: true, ContextMode: ContextModeKind.Ref })
        {
            lines.Add($"    {contextParameterName} = {parameters[0]};");
        }
        lines.Add("}");
        string closedMethod = string.Join("\n", lines);
        return interceptedVisitMethods.Count == 0
            ? closedMethod
            : closedMethod + "\n\n" + string.Join("\n", interceptedVisitMethods);
    }

    private static string RenderInterceptedParallelInvoker(IterationModel shape, InterceptionSite site)
    {
        string name = "InterceptedParallelInvoker_" + site.Id;
        string[] parameters = InterceptedParameterNames(site);
        string callbackName = "InvokeInterceptedCallback_" + site.Id;
        string countName = GeneratedLocalName(site, "count", 0);
        string indexName = GeneratedLocalName(site, "index", 0);
        string[] rowNames = GeneratorTemplates.Indexed(shape.ComponentModels.Length, index => GeneratedLocalName(site, "row", index)).ToArray();
        var fields = new List<string>();
        if (shape.HasContext)
        {
            fields.Add($"    private {InterceptedContextType(shape)} _context;");
        }
        fields.AddRange(GeneratorTemplates.Indexed(shape.ComponentModels.Length, index => $"    private readonly int _access{index};"));
        var constructorParameters = new List<string>();
        if (shape.HasContext)
        {
            constructorParameters.Add(InterceptedContextType(shape) + " context");
        }
        string accessParameters = shape.Api.Signature.AccessParameters(tokens: true);
        if (accessParameters.Length != 0)
        {
            constructorParameters.Add(accessParameters);
        }
        var constructorAssignments = new List<string>();
        if (shape.HasContext)
        {
            constructorAssignments.Add("        _context = context;");
        }
        constructorAssignments.AddRange(GeneratorTemplates.Indexed(shape.ComponentModels.Length, index =>
            $"        _access{index} = GeneratedForEachRuntime.Get{(!shape.ComponentModels[index].IsWrite ? "Read" : "Write")}QueryComponentIndex(access{index});"));
        var body = new List<string>();
        var interceptedParallelVisitMethods = new List<string>();
        bool inlineLambda = CanInlineInterceptedLambda(site);
        body.AddRange(GeneratorTemplates.Indexed(shape.ComponentModels.Length, index =>
            $"        ref {shape.ComponentModels[index].ResolvedTypeName} {rowNames[index]} = ref slots.GetGeneratedReadReference<{shape.ComponentModels[index].ResolvedTypeName}>(_access{index});"));
        if (shape.HasEntity)
        {
            int entityParameterIndex = shape.HasContext ? 1 : 0;
            body.Add("        global::Delta.ECS.GeneratedEntityRefView entityRefView = default;");
            body.Add($"        global::Delta.ECS.EntityRef {parameters[entityParameterIndex]} = slots.CreateEntityRef(ref entityRefView);");
            body.Add("        slots.BindEntityRef(ref entityRefView);");
        }
        body.Add($"        int {countName} = slots.Count;");

        if (shape.HasEntity)
        {
            int entityParameterIndex = shape.HasContext ? 1 : 0;
            var denseLoopLines = new List<string>
            {
                $"for (int {indexName} = 0; {indexName} < {countName}; {indexName}++)",
                "{",
                $"    slots.SetEntityRefSlot(ref entityRefView, slots.GetGeneratedSlotIndex({indexName}));"
            };
            for (int index = 0; index < shape.ComponentModels.Length; index++)
            {
                denseLoopLines.Add($"    {(shape.ComponentModels[index].IsWrite ? "ref " : "ref readonly ")}{shape.ComponentModels[index].ResolvedTypeName} {parameters[entityParameterIndex + 1 + index]} = ref global::System.Runtime.CompilerServices.Unsafe.Add(ref {rowNames[index]}, slots.GetGeneratedRowOffset({indexName}));");
            }

            denseLoopLines.Add(AppendCallbackBody(shape, site, inlineLambda, callbackName, parameters, "    "));
            denseLoopLines.Add("}");
            string contextSetup = shape.HasContext
                ? SignatureProjection.ContextLocal(shape.ContextMode, InterceptedContextType(shape), parameters[0], "_context")
                : string.Empty;
            if (contextSetup.Length != 0)
            {
                body.Add(contextSetup);
            }
            AppendInterceptedTagSelectionLoop(
                body,
                shape,
                site,
                "slots.HasTagFilters && slots.TryGetTagSlots(out var tagSlots)",
                string.Empty,
                callbackName,
                parameters,
                inlineLambda,
                rowNames,
                denseLoopLines);
        }
        else
        {
            var cursors = new List<(string TypeName, string Name)>();

            for (int index = 0; index < shape.ComponentModels.Length; index++)
            {
                cursors.Add((shape.ComponentModels[index].ResolvedTypeName, rowNames[index]));
            }

            (string visitRefParameters, string visitRefArguments) = BuildVisitRefLists(cursors);
            string leadingParameters = string.Empty;
            string leadingArguments = string.Empty;
            if (shape.HasContext)
            {
                string contextName = parameters[0];
                leadingParameters = SignatureProjection.ContextParameter(
                    shape.ContextMode,
                    InterceptedContextType(shape),
                    contextName);
                leadingArguments = SignatureProjection.ContextArgument(shape.ContextMode, "_context");
            }

            var visitMethods = new List<string>();
            var denseLoopLines = new List<string>();
            AppendUnrolledDenseSlotLoop(
                denseLoopLines,
                visitMethods,
                "        ",
                "    ",
                countName,
                visitRefParameters,
                visitRefArguments,
                (stepLines, stepIndent, offset, pin) =>
                {
                    int parameterIndex = shape.HasContext ? 1 : 0;
                    if (inlineLambda)
                    {
                        stepLines.AddRange(GeneratorTemplates.Indexed(shape.ComponentModels.Length, index =>
                            $"{stepIndent}{(shape.ComponentModels[index].IsWrite ? "ref " : "ref readonly ")}{shape.ComponentModels[index].ResolvedTypeName} {parameters[parameterIndex + index]} = ref {AtOffset(pin(rowNames[index]), offset)};"));
                        stepLines.Add(AppendInterceptedLambdaBody(site, stepIndent));
                    }
                    else
                    {
                        string[] callbackParameters = (string[])parameters.Clone();
                        int firstComponentParameter = shape.HasContext ? 1 : 0;
                        for (int index = 0; index < rowNames.Length; index++)
                        {
                            callbackParameters[firstComponentParameter + index] = AtOffset(pin(rowNames[index]), offset);
                        }

                        stepLines.Add(AppendCallbackInvocation(shape, callbackName, callbackParameters, stepIndent));
                    }
                },
                (advanceLines, advanceIndent, advance) =>
                {
                    advanceLines.AddRange(GeneratorTemplates.Indexed(shape.ComponentModels.Length, index =>
                        $"{advanceIndent}{rowNames[index]} = ref {UnsafeAdd(rowNames[index], advance)};"));
                },
                visitLeadingParameters: leadingParameters,
                visitLeadingArguments: leadingArguments,
                isolateSteps: true);
            string contextSetup = string.Empty;
            if (shape.HasContext)
            {
                contextSetup = SignatureProjection.ContextLocal(
                    shape.ContextMode,
                    InterceptedContextType(shape),
                    parameters[0],
                    "_context");
            }

            AppendInterceptedTagSelectionLoop(
                body,
                shape,
                site,
                "slots.HasTagFilters && slots.TryGetTagSlots(out var tagSlots)",
                contextSetup,
                callbackName,
                parameters,
                inlineLambda,
                rowNames,
                denseLoopLines);
            interceptedParallelVisitMethods = visitMethods;
        }

        string members = string.Join("\n", new[]
        {
            string.Join("\n", fields),
            $$"""
                public {{name}}({{string.Join(", ", constructorParameters)}})
                {
                {{GeneratorTemplates.Indent(string.Join("\n", constructorAssignments), "    ")}}
                }
            """.Trim(),
            $"    public bool RequiresSingleThread => {(shape.ContextMode == ContextModeKind.Ref ? "true" : "false")};",
            "    [global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]",
            "    public void Invoke(ref GeneratedQuerySlots slots)",
            "    {",
            string.Join("\n", body),
            "    }",
            string.Join("\n", interceptedParallelVisitMethods),
            shape.HasContext ? $"    internal {InterceptedContextType(shape)} Context => _context;" : string.Empty,
        }.Where(static value => !string.IsNullOrEmpty(value)));
        return GeneratorTemplates.RenderBlock($"private struct {name} : IGeneratedParallelInvoker", members);
    }

    private static string AppendCallbackInvocation(IterationModel shape, string target, string[] parameters, string indent)
    {
        var invocationArguments = new List<string>();
        int parameterIndex = 0;
        if (shape.HasContext)
        {
            invocationArguments.Add(SignatureProjection.ContextArgument(shape.ContextMode, parameters[parameterIndex++]));
        }

        if (shape.HasEntity)
        {
            invocationArguments.Add(parameters[parameterIndex++]);
        }
        invocationArguments.AddRange(Enumerable.Range(0, shape.ComponentModels.Length)
            .Select(index => shape.Api.Signature.ComponentArgument(index, parameters[parameterIndex + index])));
        return indent + target + "(" + string.Join(", ", invocationArguments) + ");";
    }

    private static string RenderInterceptedParallelClosedMethod(IterationModel shape, InterceptionSite site)
    {
        IterationModel accessShape = new(
            shape.RegistrationBinding,
            shape.HasEntity,
            shape.HasContext,
            isFunctor: true,
            shape.Pattern,
            shape.Components,
            functorType: null,
            contextType: shape.ContextType,
            parallel: shape.Parallel,
            contextMode: shape.ContextMode,
            methodName: shape.MethodName,
            hasEntityTarget: shape.HasEntityTarget,
            hasQuery: true,
            typeBinding: TypeBindingKind.CallbackInferred);
        string[] parameters = InterceptedParameterNames(site);
        string methodName = "ExecuteInterceptedClosed_" + site.Id;
        string invokerType = "InterceptedParallelInvoker_" + site.Id;
        SignatureProjection slots = shape.Api.Signature;
        string componentParameters = slots.HasExplicitIds ? ", " + slots.ComponentIdParameters("componentId") : string.Empty;
        string contextParameter = shape.HasContext
            ? ", " + SignatureProjection.ContextParameter(shape.ContextMode, InterceptedContextType(shape), parameters[0])
            : string.Empty;
        string target = shape.HasEntityTarget ? ", global::System.ReadOnlySpan<global::Delta.ECS.Entity> entities" : string.Empty;
        string signature = $"private static void {methodName}(global::Delta.ECS.World world{target}, in global::Delta.ECS.Query query{componentParameters}{contextParameter}{(shape.Parallel ? ", int workerCount" : string.Empty)})";
        string constructorArguments = string.Join(", ", new[]
        {
            shape.HasContext ? parameters[0] : null,
            slots.AccessArguments(),
        }.Where(static value => !string.IsNullOrEmpty(value)));
        string execute = shape.HasEntityTarget
            ? $"GeneratedForEachRuntime.ExecuteEntityList{(shape.Parallel ? "Parallel" : string.Empty)}(world, in query, entities, ref invoker, {AppendParallelWriteIndices(accessShape)}{(shape.Parallel ? ", workerCount" : string.Empty)});"
            : $"GeneratedForEachRuntime.ExecuteParallelDense(world, in query, ref invoker, {AppendParallelWriteIndices(accessShape)}, workerCount);";
        string body = $"""
                GeneratedForEachRuntime.ValidateGeneratedWhere(world, in query);
                {(slots.HasDynamicIds ? $"GeneratedForEachRuntime.ValidateComponentIdCount(componentIds, {slots.Arity});" : string.Empty)}
                {GeneratorTemplates.Indent(AccessSetup(accessShape).TrimEnd(), "    ")}
                var invoker = new {invokerType}({constructorArguments});
                {execute}
                {(shape is { HasContext: true, ContextMode: ContextModeKind.Ref } ? parameters[0] + " = invoker.Context;" : string.Empty)}
            """;
        string declaration = $"""
            [global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
            {signature}
            """.Trim();
        return GeneratorTemplates.RenderBlock(declaration, body);
    }

    private static string[] InterceptedParameterNames(InterceptionSite site) =>
        site.Binding.LambdaParameterNames;

    private static string RenderInterceptor(IterationModel shape, InterceptionSite site)
    {
        SignatureProjection slots = shape.Api.Signature;
        bool specializedInvoker = SupportsDirectExecution(site);
        var parameters = new List<string> { "this global::Delta.ECS.World world" };
        if (shape.HasEntityTarget)
        {
            parameters.Add("global::System.ReadOnlySpan<global::Delta.ECS.Entity> entities");
        }

        if (shape.HasQuery)
        {
            parameters.Add("in global::Delta.ECS.Query query");
        }
        if (slots.HasExplicitIds)
        {
            parameters.Add(slots.ComponentIdParameters("componentId"));
        }
        if (shape.HasContext)
        {
            parameters.Add(SignatureProjection.ContextParameter(shape.ContextMode, InterceptedContextType(shape), "context"));
        }

        parameters.Add(GeneratorSupport.QualifiedName(
            shape.ComponentModels.Length == 0 ? GeneratorSupport.EcsNamespace : shape.Namespace,
            ConcreteActionType(shape)) + " _");
        if (shape.Parallel)
        {
            parameters.Add("int workerCount = 0");
        }
        var setup = new List<string>();
        if (shape.HasEntityTarget)
        {
            setup.Add("global::Delta.ECS.Entity[] operationEntities = entities.ToArray();");
        }

        if (slots.HasDynamicIds)
        {
            setup.Add("global::Delta.ECS.ComponentId[] operationComponentIds = componentIds.ToArray();");
        }

        if (shape.HasQuery)
        {
            setup.Add("global::Delta.ECS.Query operationQuery = query;");
        }
        else if (slots.HasExplicitIds)
        {
            setup.Add(slots.HasDynamicIds
                ? "global::Delta.ECS.Query operationQuery = world.WhereAll(operationComponentIds);"
                : $$"""
                global::Delta.ECS.Query operationQuery = world.WhereAll(stackalloc global::Delta.ECS.ComponentId[]
                {
                    {{slots.ComponentIdArguments("componentId")}}
                });
                """);
        }
        else
        {
            setup.Add($"global::System.ReadOnlySpan<global::Delta.ECS.ComponentId> operationComponents = {GeneratorTemplates.PrimaryComponentIds("world", shape.Components, namespaceName: shape.Namespace)};");
            setup.Add("global::Delta.ECS.Query operationQuery = world.WhereAll(operationComponents);");
        }

        bool mutableContext = shape.HasContext && shape.ContextMode == ContextModeKind.Ref;
        string invokerGeneric = shape.IsFunctor
            ? string.Empty
            : SignatureProjection.TypeArguments(SignatureProjection.JoinGeneric(
                shape.HasContext && ContextType(shape) == "TContext" ? InterceptedContextType(shape) : string.Empty,
                slots.HasGenericSelectors ? string.Join(", ", shape.Components) : string.Empty));
        string extensionType = GeneratorSupport.QualifiedName(shape.Namespace, "DemandForEachExtensions_" + GeneratorSupport.StableName(shape.Key));
        string invokerType = extensionType + "." + OperationInvokerName(shape) + invokerGeneric;
        string operationType = OperationType(shape, invokerType, InterceptedContextType(shape));
        var invokerArguments = new List<string> { "world" };
        if (shape.HasEntityTarget)
        {
            invokerArguments.Add("operationEntities");
        }

        invokerArguments.Add("operationQuery");

        if (slots.HasExplicitIds)
        {
            invokerArguments.Add(slots.HasDynamicIds
                ? "operationComponentIds"
                : slots.ComponentIdArguments("componentId"));
        }

        if (shape.HasContext && !mutableContext)
        {
            invokerArguments.Add("context");
        }

        if (!shape.IsFunctor)
        {
            invokerArguments.Add(specializedInvoker ? "ExecuteInterceptedClosed_" + site.Id : "_");
        }

        if (shape.Parallel)
        {
            invokerArguments.Add("workerCount");
        }

        string invoker = $"new {invokerType}({string.Join(", ", invokerArguments)})";
        string operation = mutableContext
            ? $"new {operationType}(context, {invoker})"
            : $"new {operationType}({invoker})";
        string body = string.Join("\n", setup) + "\nreturn " + operation + ";";
        string declaration = $"""
            [global::System.Runtime.CompilerServices.MethodImpl(global::System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
            {site.Attribute}
            internal static {operationType} Intercept_{site.Id}({string.Join(", ", parameters)})
            """.Trim();
        return GeneratorTemplates.Indent(GeneratorTemplates.RenderBlock(declaration, body), "    ");
    }

    private static string ConcreteActionType(IterationModel shape)
    {
        string suffix = IsAllWrite(shape.ComponentModels) ? string.Empty : "_" + shape.Pattern;
        string generic = string.Join(", ", shape.Components);
        if (!shape.HasContext)
        {
            return SignatureProjection.TypeWithArguments(
                (shape.HasEntity ? "ForEachEntityAction" : "ForEachAction") + suffix,
                generic);
        }

        generic = SignatureProjection.JoinGeneric(InterceptedContextType(shape), generic);
        return SignatureProjection.TypeWithArguments(
            (shape.HasEntity ? "ForEachContextEntityAction" : "ForEachContextAction") + ContextDelegateSuffix(shape.ContextMode) + suffix,
            generic);

    }

    private static string InterceptedContextType(IterationModel shape) => shape.ContextType ?? "global::System.Object";

    private static string RenderClosedDenseMethod(
        IterationModel shape,
        string methodName,
        string componentParameters,
        bool cachePreparedAccess = false)
    {
        SignatureProjection slots = shape.Api.Signature;
        string generic = slots.HasGenericSelectors ? slots.GenericList() : string.Empty;
        string genericPrefix = StateGeneric(shape, generic);
        string contextParameter = shape.HasContext
            ? ", " + SignatureProjection.ContextParameter(shape.ContextMode, ContextType(shape), "context")
            : string.Empty;
        string callbackParameter = shape.IsFunctor
            ? ", " + SignatureProjection.ContextParameter(shape.FunctorPassMode, shape.FunctorType!, "functor")
            : ", " + ActionType(shape) + " action";
        string target = shape.HasEntityTarget ? ", global::System.ReadOnlySpan<Entity> entities, in Query query" : ", in Query query";
        string cachedAccessParameters = cachePreparedAccess ? ", " + slots.AccessParameters(tokens: true) : string.Empty;
        bool copyRefContext = shape is { HasContext: true, ContextMode: ContextModeKind.Ref };
        string contextName = copyRefContext ? "contextCopy" : "context";
        string signature = $"private static void {methodName}{genericPrefix}(World world{target}{cachedAccessParameters}{componentParameters}{contextParameter}{callbackParameter})";
        var lines = new List<string>
        {
            "[System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]",
            signature,
            "{",
            slots.HasDynamicIds && !cachePreparedAccess
                ? $"    GeneratedForEachRuntime.ValidateComponentIdCount(componentIds, {slots.Arity});"
                : string.Empty,
            cachePreparedAccess ? string.Empty : GeneratorTemplates.Indent(AccessSetup(shape).TrimEnd(), "    "),
        };
        var closedDenseVisitMethods = new List<string>();
        if (copyRefContext && !shape.HasEntityTarget)
        {
            lines.Add($"    {ContextType(shape)} contextCopy = context;");
        }
        if (shape.HasEntityTarget)
        {
            string invokerType = ParallelInvokerName(shape) + StateGeneric(shape, generic);
            string arguments = string.Join(", ", new[]
            {
                shape.HasContext ? "context" : null,
                shape.IsFunctor ? "functor" : "action",
                slots.AccessArguments(),
            }.Where(static value => !string.IsNullOrEmpty(value)));
            lines.Add($"    var invoker = new {invokerType}({arguments});");
            lines.Add($"    GeneratedForEachRuntime.ExecuteEntityList(world, in query, entities, ref invoker, {AppendParallelWriteIndices(shape)});");
            if (shape is { HasContext: true, ContextMode: ContextModeKind.Ref })
            {
                lines.Add("    context = invoker.Context;");
            }

            if (shape is { IsFunctor: true, FunctorPassMode: ContextModeKind.Ref })
            {
                lines.Add("    functor = invoker.Functor;");
            }
            lines.Add("}");
            return GeneratorTemplates.Indent(string.Join("\n", lines), "    ");
        }

        if (shape.HasEntity)
        {
            lines.Add("    GeneratedEntityRefView entityRefView = default;");
            lines.Add("    EntityRef entity = GeneratedForEachRuntime.CreateEntityRef(world, ref entityRefView);");
        }

        if (shape.IsFunctor)
        {
            lines.Add("    var action = functor;");
        }
        lines.Add($"    using var execution = GeneratedForEachRuntime.{(shape.ComponentModels.Any(static component => component.IsWrite) ? "OpenWriteDense" : "OpenReadDense")}(world, in query);");
        lines.AddRange(SplitLines(AppendQueryComponentRoutes(shape, "    ")));
        lines.AddRange(SplitLines(AppendArchetypeWriteSetup(shape, "    ")));
        for (int index = 0; index < shape.ComponentModels.Length; index++)
        {
            string type = ComponentType(shape, index);
            lines.Add($"    ref {type} component{index} = ref global::System.Runtime.CompilerServices.Unsafe.NullRef<{type}>();");
        }

        var denseLoopLines = new List<string>();
        var visitMethods = new List<string>();
        if (shape.HasEntity)
        {
            denseLoopLines.Add("for (int index = 0; index < count; index++)");
            denseLoopLines.Add("{");
            denseLoopLines.Add("    slots.SetEntityRefSlot(ref entityRefView, slots.GetGeneratedSlotIndex(index));");
            denseLoopLines.AddRange(GeneratorTemplates.Indexed(shape.ComponentModels.Length, index =>
                $"    ref {ComponentType(shape, index)} current{index} = ref global::System.Runtime.CompilerServices.Unsafe.Add(ref component{index}, slots.GetGeneratedRowOffset(index));"));
            denseLoopLines.Add("    " + AppendClosedInvocation(
                shape,
                "action",
                "action",
                contextName,
                "current",
                "entity",
                index => $"current{index}") + ";");
            denseLoopLines.Add("}");
        }
        else
        {
            var cursors = new List<(string TypeName, string Name)>();

            for (int index = 0; index < shape.ComponentModels.Length; index++)
            {
                cursors.Add((ComponentType(shape, index), $"component{index}"));
            }

            (string visitRefParameters, string visitRefArguments) = BuildVisitRefLists(cursors);
            var leading = new List<string>();
            var leadingArgs = new List<string>();
            if (shape.HasContext)
            {
                leading.Add(SignatureProjection.ContextParameter(shape.ContextMode, ContextType(shape), contextName));
                leadingArgs.Add(SignatureProjection.ContextArgument(shape.ContextMode, contextName));
            }

            if (shape.IsFunctor)
            {
                // Hot loop uses a local `action` copy so ref functors can write back after the loop.
                leading.Add(SignatureProjection.ContextParameter(shape.FunctorPassMode, shape.FunctorType!, "action"));
                leadingArgs.Add(SignatureProjection.ContextArgument(shape.FunctorPassMode, "action"));
            }
            else
            {
                leading.Add($"{ActionType(shape)} action");
                leadingArgs.Add("action");
            }

            AppendUnrolledDenseSlotLoop(
                denseLoopLines,
                visitMethods,
                "        ",
                string.Empty,
                "count",
                visitRefParameters,
                visitRefArguments,
                (stepLines, stepIndent, offset, pin) =>
                {
                    string invocation = AppendClosedInvocation(
                        shape,
                        "action",
                        "action",
                        contextName,
                        "component",
                        string.Empty,
                        index => AtOffset(pin("component" + index), offset));
                    stepLines.Add($"{stepIndent}{invocation};");
                },
                (advanceLines, advanceIndent, advance) =>
                {
                    advanceLines.AddRange(GeneratorTemplates.Indexed(shape.ComponentModels.Length,
                        index => $"{advanceIndent}component{index} = ref {UnsafeAdd($"component{index}", advance)};"));
                },
                visitLeadingParameters: string.Join(", ", leading),
                visitLeadingArguments: string.Join(", ", leadingArgs),
                visitMethodGenerics: genericPrefix);
        }

        void AppendChunkLoop(bool filterTagSlots)
        {
            lines.Add(shape.HasEntity
                ? "        while (execution.MoveNextTrusted(out var slots))"
                : "        while (execution.MoveNextTrusted(out var componentRows, out int count))");
            lines.Add("        {");

            if (shape.HasEntity)
            {
                lines.Add("            slots.BindEntityRef(ref entityRefView);");
            }

            for (int index = 0; index < shape.ComponentModels.Length; index++)
            {
                string type = ComponentType(shape, index);
                lines.Add(shape.HasEntity
                    ? $"                component{index} = ref GeneratedForEachRuntime.GetGeneratedArrayReference(slots.GetGeneratedArray<{type}>(access{index}));"
                    : $"                component{index} = ref GeneratedForEachRuntime.GetGeneratedRow<{type}>(componentRows, route{index});");
            }

            if (filterTagSlots)
            {
                AppendUnboundTagSelectionLoop(lines, shape, contextName, denseLoopLines);
            }
            else
            {
                lines.AddRange(denseLoopLines);
            }

            lines.Add("        }");
        }

        PrependDenseLoopCount(denseLoopLines, shape.HasEntity, "count");

        AppendChunkFilterBranch(lines, AppendChunkLoop);

        closedDenseVisitMethods = visitMethods;
        if (shape is { IsFunctor: true, FunctorPassMode: ContextModeKind.Ref })
        {
            lines.Add("    functor = action;");
        }
        if (copyRefContext)
        {
            lines.Add("    context = contextCopy;");
        }
        lines.Add("}");
        string closedMethod = GeneratorTemplates.Indent(string.Join("\n", lines), "    ");
        if (closedDenseVisitMethods.Count == 0)
        {
            return closedMethod;
        }

        string visitHelpers = string.Join("\n", closedDenseVisitMethods.Select(static line =>
            string.IsNullOrEmpty(line) ? line : "    " + line));
        return closedMethod + "\n\n" + visitHelpers;
    }

    private static string[] SplitLines(string text) => string.IsNullOrEmpty(text) ? [] : text.TrimEnd().Split(["\r\n", "\n"], StringSplitOptions.None);

    private static string RenderExtensionMethod(
        IterationModel shape,
        string prefix,
        string query,
        string contextParameter,
        string ids,
        string callback,
        string genericPrefix,
        string className,
        bool profiling,
        string closedMethodName)
    {
        string componentPart = string.IsNullOrEmpty(ids) ? string.Empty : $", {ids}";
        string methodName = shape.MethodName;
        string profileName = className + "." + methodName;
        string callbackName = shape.IsFunctor ? "functor" : "action";
        string callbackParameter = shape.IsFunctor
            ? ", " + SignatureProjection.ContextParameter(shape.FunctorPassMode, shape.FunctorType!, callbackName)
            : ", " + callback + " " + callbackName;
        string workerCountParameter = shape.Parallel ? ", int workerCount = 0" : string.Empty;
        string visibility = shape.IsFunctor || shape.ImplicitComponents ? "internal" : "public";
        string operationType = OperationType(shape);
        string signature = $"{visibility} static {operationType} {methodName}{genericPrefix}({prefix}{query}{componentPart}{contextParameter}{callbackParameter}{workerCountParameter})";
        string body = BuildDeferredBody(
            shape,
            profiling,
            StableProfileMethodId(profileName),
            closedMethodName);
        return GeneratorTemplates.Indent(
            RenderMethod(
                GeneratorTemplates.Documentation(shape.Api),
                signature,
                body,
                profiling ? profileName : null),
            "    ");
    }

    private static string OperationType(IterationModel shape) => OperationType(shape, OperationInvokerType(shape));

    private static bool CachesPreparedAccess(IterationModel shape) => !shape.Parallel && !shape.HasEntityTarget
            && shape.ComponentModels.Length > 0;

    private static string OperationType(IterationModel shape, string invoker, string? contextType = null)
    {
        bool mutableContext = shape.HasContext && shape.ContextMode == ContextModeKind.Ref;
        string? operationContext = mutableContext ? contextType ?? ContextType(shape) : null;
        string? operationFunctor = shape.IsFunctor ? shape.FunctorType : null;
        return EcsOperationTemplates.OperationType(invoker, operationContext, operationFunctor);
    }

    private static string OperationInvokerName(IterationModel shape) => "DemandForEachOperationInvoker_" + GeneratorSupport.StableName(shape.Key);

    private static string OperationInvokerGenericParameters(IterationModel shape)
    {
        string generic = shape.Api.Signature.HasGenericSelectors
            ? shape.Api.Signature.GenericList()
            : string.Empty;
        if (shape.HasContext && ContextType(shape) == "TContext")
        {
            generic = SignatureProjection.JoinGeneric("TContext", generic);
        }

        if (shape.OrderedWhereSource is { } whereSource)
        {
            generic = SignatureProjection.JoinGeneric(
                generic,
                GeneratedWhereTemplates.ViewMethodTypeParameters(whereSource));
        }

        return SignatureProjection.TypeArguments(generic);
    }

    private static string OperationInvokerType(IterationModel shape) => OperationInvokerName(shape) + OperationInvokerGenericParameters(shape);

    private static string RenderOperationInvoker(IterationModel shape, string closedMethodName, bool profiling, int methodId, bool hasInterceptedExecution)
    {
        string genericParameters = OperationInvokerGenericParameters(shape);
        bool mutableContext = shape.HasContext && shape.ContextMode == ContextModeKind.Ref;
        string? contextType = mutableContext ? ContextType(shape) : null;
        string? functorType = shape.IsFunctor ? shape.FunctorType : null;
        string stateInterface = EcsOperationTemplates.InvokerInterface(contextType, functorType);
        string visibility = shape.IsFunctor || shape.ImplicitComponents ? "internal" : "public";
        var fields = new List<string>
        {
            "private readonly global::Delta.ECS.World _world;",
            shape.HasEntityTarget ? "private readonly global::Delta.ECS.Entity[] _entities;" : string.Empty,
            "private readonly global::Delta.ECS.Query _query;"
        };
        AppendCachedAccessFields(shape, fields);
        var constructorParameters = new List<string>
        {
            "global::Delta.ECS.World world",
            shape.HasEntityTarget ? "global::Delta.ECS.Entity[] entities" : string.Empty,
            "global::Delta.ECS.Query query"
        };
        var constructorAssignments = new List<string>
        {
            "_world = world;",
            shape.HasEntityTarget ? "_entities = entities;" : string.Empty,
            "_query = query;"
        };
        AppendOperationInvokerMembers(shape, fields, constructorParameters, constructorAssignments);
        if (hasInterceptedExecution)
        {
            fields.Add($"private readonly {InterceptedExecutionName(shape)}? _interceptedExecution;");
            constructorAssignments.Add("_interceptedExecution = null;");
        }

        string methods = RenderOperationInvokerMethods(shape, closedMethodName, profiling, methodId, stateInterface, hasInterceptedExecution);
        if (hasInterceptedExecution)
        {
            string executionDelegate = InterceptedExecutionName(shape);
            methods = $$"""
                internal {{OperationInvokerName(shape)}}(global::Delta.ECS.World world, global::Delta.ECS.Query query, {{executionDelegate}} interceptedExecution)
                {
                    _world = world;
                    _query = query;
                    _action = null!;
                    _interceptedExecution = interceptedExecution;
                }

            {{methods}}
            """;
        }

        return EcsOperationTemplates.InvokerStruct(
            visibility,
            OperationInvokerName(shape),
            genericParameters,
            stateInterface,
            string.Empty,
            GeneratorTemplates.JoinNonEmpty(fields),
            string.Join(", ", constructorParameters.Where(static parameter => parameter.Length != 0)),
            GeneratorTemplates.JoinNonEmpty(constructorAssignments),
            methods);
    }

    private static void AppendOperationInvokerMembers(
        IterationModel shape,
        List<string> fields,
        List<string> constructorParameters,
        List<string> assignments)
    {
        bool mutableContext = shape.HasContext && shape.ContextMode == ContextModeKind.Ref;
        fields.Add(shape.Api.Signature.ComponentIdFields());
        fields.Add(shape.HasContext && !mutableContext ? $"private readonly {ContextType(shape)} _context;" : string.Empty);
        fields.Add(shape.IsFunctor ? string.Empty : $"private readonly {ActionType(shape)} _action;");
        fields.Add(shape.Parallel ? "private readonly int _workerCount;" : string.Empty);
        constructorParameters.Add(shape.Api.Signature.ComponentIdStorageParameters());
        constructorParameters.Add(shape.HasContext && !mutableContext ? ContextType(shape) + " context" : string.Empty);
        constructorParameters.Add(shape.IsFunctor ? string.Empty : ActionType(shape) + " action");
        constructorParameters.Add(shape.Parallel ? "int workerCount" : string.Empty);
        assignments.Add(shape.Api.Signature.ComponentIdAssignments());
        assignments.Add(shape.HasContext && !mutableContext ? "_context = context;" : string.Empty);
        assignments.Add(shape.IsFunctor ? string.Empty : "_action = action;");
        assignments.Add(shape.Parallel ? "_workerCount = workerCount;" : string.Empty);
    }

    private static void AppendCachedAccessFields(IterationModel shape, List<string> fields)
    {
        if (!CachesPreparedAccess(shape))
        {
            return;
        }

        fields.Add("private bool _cachedAccessPrepared;");
        fields.AddRange(GeneratorTemplates.Indexed(shape.ComponentModels.Length, index =>
            $"private {(shape.ComponentModels[index].IsWrite ? "WriteAccess" : "ReadAccess")} _access{index};"));
    }

    private static string RenderOperationInvokerMethods(
        IterationModel shape,
        string closedMethodName,
        bool profiling,
        int methodId,
        string stateInterface,
        bool hasInterceptedExecution)
    {
        _ = shape.Api.Signature.HasGenericSelectors ? shape.Api.Signature.GenericList() : string.Empty;
        string contextName = shape.HasContext
            ? shape.ContextMode == ContextModeKind.Ref ? "context" : "contextCopy"
            : "context";
        string functorName = "functor";
        var lines = new List<string>
        {
            hasInterceptedExecution
                ? "if (_interceptedExecution is { } interceptedExecution) { interceptedExecution(_world, in _query); return; }"
                : string.Empty,
            "global::Delta.ECS.World world = _world;",
            shape.HasEntityTarget ? "global::Delta.ECS.Entity[] operationEntities = _entities;" : string.Empty,
            "global::Delta.ECS.Query operationQuery = _query;",
            CachesPreparedAccess(shape) ? string.Empty : shape.Api.Signature.ComponentIdLocals("operationComponentIds"),
            shape.HasContext && shape.ContextMode != ContextModeKind.Ref
                ? $"{ContextType(shape)} contextCopy = _context;"
                : string.Empty,
            shape.IsFunctor ? string.Empty : $"{ActionType(shape)} action = _action;",
            shape.Parallel ? "int workerCount = _workerCount;" : string.Empty,
            BuildBody(shape, profiling, methodId, closedMethodName, contextName, functorName)
        };
        string body = GeneratorTemplates.JoinNonEmpty(lines);
        bool mutableContext = shape.HasContext && shape.ContextMode == ContextModeKind.Ref;
        string? contextType = mutableContext ? ContextType(shape) : null;
        string? functorType = shape.IsFunctor ? shape.FunctorType : null;
        string method = EcsOperationTemplates.InvokeMethod(stateInterface, contextType, functorType);
        return GeneratorTemplates.RenderBlock(method, body);
    }

    private static string BuildDeferredBody(IterationModel shape, bool profiling, int methodId, string closedMethodName)
    {
        bool mutableContext = shape.HasContext && shape.ContextMode == ContextModeKind.Ref;
        var setup = new List<string>();
        if (shape.HasEntityTarget)
        {
            setup.Add("global::Delta.ECS.Entity[] operationEntities = entities.ToArray();");
        }

        if (shape.Api.Signature.HasDynamicIds)
        {
            setup.Add("global::Delta.ECS.ComponentId[] operationComponentIds = componentIds.ToArray();");
        }

        if (shape.HasQuery)
        {
            setup.Add("global::Delta.ECS.Query operationQuery = query;");
        }
        else if (shape.Api.Signature.HasExplicitIds)
        {
            string ids = shape.Api.Signature.HasDynamicIds
                ? "operationComponentIds"
                : shape.Api.Signature.ComponentIdArguments("componentId");
            setup.Add($"global::Delta.ECS.Query operationQuery = world.WhereAll({ids});");
        }
        else
        {
            string components = GeneratorTemplates.PrimaryComponentIds(
                "world",
                GeneratorTemplates.Indexed(shape.ComponentModels.Length, index => ComponentType(shape, index)).ToArray(),
                namespaceName: shape.Namespace);
            setup.Add($"global::System.ReadOnlySpan<global::Delta.ECS.ComponentId> operationComponents = {components};");
            setup.Add("global::Delta.ECS.Query operationQuery = world.WhereAll(operationComponents);");
        }

        var invokerArguments = new List<string> { "world" };
        if (shape.HasEntityTarget)
        {
            invokerArguments.Add("operationEntities");
        }

        invokerArguments.Add("operationQuery");
        if (shape.Api.Signature.HasDynamicIds)
        {
            invokerArguments.Add("operationComponentIds");
        }
        else if (shape.Api.Signature.HasExplicitIds)
        {
            invokerArguments.Add(shape.Api.Signature.ComponentIdArguments("componentId"));
        }

        if (shape.HasContext && !mutableContext)
        {
            invokerArguments.Add("context");
        }

        if (!shape.IsFunctor)
        {
            invokerArguments.Add("action");
        }

        if (shape.Parallel)
        {
            invokerArguments.Add("workerCount");
        }

        string invoker = $"new {OperationInvokerType(shape)}({string.Join(", ", invokerArguments)})";
        string operation = EcsOperationTemplates.CreationExpression(
            OperationType(shape),
            invoker,
            mutableContext ? ContextType(shape) : null,
            shape.IsFunctor ? shape.FunctorType : null);
        setup.Add($"return {operation};");
        return GeneratorTemplates.RenderBlock(string.Empty, string.Join("\n", setup));
    }

    private static string BuildBody(
        IterationModel shape,
        bool profiling,
        int methodId,
        string closedMethodName,
        string contextName,
        string functorName)
    {
        SignatureProjection slots = shape.Api.Signature;
        bool cachePreparedAccess = CachesPreparedAccess(shape);
        var closedArguments = new List<string>(shape.HasEntityTarget
            ? new[] { "world", "operationEntities", "in operationQuery" }
            : ["world", "in operationQuery"]);
        if (cachePreparedAccess)
        {
            closedArguments.Add(slots.AccessArguments("_access"));
        }
        if (slots.HasExplicitIds && !cachePreparedAccess)
        {
            closedArguments.Add(slots.HasDynamicIds ? "operationComponentIds" : slots.ComponentIdArguments("componentId"));
        }

        if (shape.HasContext)
        {
            closedArguments.Add(SignatureProjection.ContextArgument(shape.ContextMode, contextName));
        }

        closedArguments.Add(shape.IsFunctor
            ? SignatureProjection.ContextArgument(shape.FunctorPassMode, functorName)
            : "action");
        if (shape.Parallel)
        {
            closedArguments.Add("workerCount");
        }

        string invoke = closedMethodName + StateGeneric(shape, slots.HasGenericSelectors ? slots.GenericList() : string.Empty)
            + "(" + string.Join(", ", closedArguments) + ");";
        var lines = new List<string>();
        string indent = "    ";
        if (profiling)
        {
            lines.Add($"    global::DeltaECS.Profiling.ProfilerRuntime.Enter({methodId});");
            lines.Add("    try");
            lines.Add("    {");
            indent = "        ";
        }
        if (!shape.IsFunctor && !cachePreparedAccess)
        {
            lines.Add(indent + "global::Delta.ECS.GeneratedForEachRuntime.ThrowIfNull(action, nameof(action));");
        }

        if (cachePreparedAccess)
        {
            lines.Add(GeneratorTemplates.Indent(BuildCachedAccessPreparation(shape), indent));
        }

        lines.Add(indent + invoke);
        if (cachePreparedAccess)
        {
            lines.Add(indent + "if (prepareAccess) _cachedAccessPrepared = true;");
        }
        if (profiling)
        {
            lines.Add("    }");
            lines.Add("    finally");
            lines.Add("    {");
            lines.Add($"        global::DeltaECS.Profiling.ProfilerRuntime.Leave({methodId});");
            lines.Add("    }");
        }
        return string.Join("\n", lines);
    }

    private static string BuildCachedAccessPreparation(IterationModel shape)
    {
        var lines = new List<string>
        {
            "bool prepareAccess = !_cachedAccessPrepared;",
            "if (prepareAccess)",
            "{",
            shape.IsFunctor
                ? string.Empty
                : "    global::Delta.ECS.GeneratedForEachRuntime.ThrowIfNull(action, nameof(action));",
            "    global::Delta.ECS.GeneratedForEachRuntime.ValidateGeneratedWhere(world, in operationQuery);",
            GeneratorTemplates.Indent(shape.Api.Signature.ComponentIdLocals(), "    "),
            "    global::Delta.ECS.Query query = operationQuery;",
            shape.Api.Signature.HasDynamicIds
                ? $"    global::Delta.ECS.GeneratedForEachRuntime.ValidateComponentIdCount(componentIds, {shape.Api.Signature.Arity});"
                : string.Empty,
            GeneratorTemplates.Indent(AccessSetup(shape).TrimEnd(), "    "),
            GeneratorTemplates.Indent(GeneratorTemplates.JoinNonEmpty(GeneratorTemplates.Indexed(shape.ComponentModels.Length, index =>
                $"_access{index} = access{index};")), "    "),
            "}"
        };
        return GeneratorTemplates.JoinNonEmpty(lines);
    }

    private static string RenderMethod(string documentation, string signature, string body, string? profileName)
    {
        string profile = profileName is null
            ? string.Empty
            : $"""
                [global::DeltaECS.Profiling.ProfiledMethodMetadataAttribute({StableProfileMethodId(profileName)}, "{profileName}")]
                """.TrimEnd();
        return $"""
            {documentation}
            {profile}
            [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.AggressiveInlining)]
            {signature}
            {GeneratorTemplates.Indent(body, "    ")}
            """.TrimEnd();
    }

    private static string AppendArchetypeWriteSetup(IterationModel shape, string indent)
    {
        string[] routes = GeneratorTemplates.WriteIndices(shape.ComponentModels).Select(index => "route" + index).ToArray();
        return routes.Length == 0
            ? string.Empty
            : $"{indent}execution.RecordComponentWrites(stackalloc int[] {{ {string.Join(", ", routes)} }});";
    }

    private static string AppendQueryComponentRoutes(IterationModel shape, string indent)
    {
        return string.Join("\n", GeneratorTemplates.Indexed(
            shape.ComponentModels.Length,
            index => !shape.HasEntity || shape.ComponentModels[index].IsWrite,
            index => $"{indent}int route{index} = GeneratedForEachRuntime.Get{(shape.ComponentModels[index].IsWrite ? "Write" : "Read")}QueryComponentIndex(access{index});"
            ));
    }

    private static string AccessSetup(IterationModel shape)
    {
        SignatureProjection slots = shape.Api.Signature;
        return string.Join("\n", GeneratorTemplates.Indexed(shape.ComponentModels.Length, index =>
        {
            string componentType = ComponentType(shape, index);
            string variable = "var access" + index;
            string accessKind = shape.ComponentModels[index].IsWrite ? "Write" : "Read";
            string method = "GetPrepared" + accessKind + "Access";
            string generic = slots.HasExplicitIds ? string.Empty : $"<{componentType}>";
            string arguments = string.Join(", ", new[]
            {
                "in query",
                slots.HasExplicitIds ? slots.ComponentIdArgument(index, "componentId") : null,
                slots.HasExplicitIds ? $"typeof({componentType})" : null,
            }.Where(static value => !string.IsNullOrEmpty(value)));
            return $"{variable} = GeneratedForEachRuntime.{method}{generic}({arguments});";
        }));
    }

    private static string ActionType(IterationModel shape)
    {
        SignatureProjection slots = shape.Api.Signature;
        string generic = slots.HasGenericSelectors
            ? slots.GenericList()
            : string.Join(", ", shape.ComponentModels.Select(static component => component.ResolvedTypeName));
        string suffix = IsAllWrite(shape.ComponentModels) ? string.Empty : "_" + shape.Pattern;
        if (shape.HasContext)
        {
            string contextSuffix = ContextDelegateSuffix(shape.ContextMode);
            return SignatureProjection.TypeWithArguments(
                (shape.HasEntity ? "ForEachContextEntityAction" : "ForEachContextAction") + contextSuffix + suffix,
                SignatureProjection.JoinGeneric(shape.IsFunctor || !slots.HasGenericSelectors ? ContextType(shape) : "TContext", generic));
        }

        return SignatureProjection.TypeWithArguments(shape.HasEntity ? "ForEachEntityAction" + suffix : "ForEachAction" + suffix, generic);
    }

    private static string ContextDelegateSuffix(ContextModeKind mode) => mode switch
    {
        ContextModeKind.In => "In",
        ContextModeKind.RefReadonly => "RefReadonly",
        ContextModeKind.Value => "Value",
        _ => string.Empty
    };

    private static string StateGeneric(IterationModel shape, string generic)
        => !shape.Api.Signature.HasGenericSelectors
            ? string.Empty
            : SignatureProjection.TypeArguments(shape.IsFunctor
                ? generic
                : shape.HasContext ? SignatureProjection.JoinGeneric("TContext", generic) : generic);

    private static string ParallelInvokerName(IterationModel shape) => "DemandForEachParallelInvoker_" + GeneratorSupport.StableName(shape.Key);
    private static string ComponentType(IterationModel shape, int index) => shape.ComponentModels[index].TypeName;

    private static string ContextType(IterationModel shape) => shape.IsFunctor || shape.ImplicitComponents
            ? shape.ContextType ?? "TContext"
            : "TContext";

    private static string ConstructorName(string name)
    {
        int index = name.IndexOf('<');
        return index < 0 ? name : name.Substring(0, index);
    }

    private static bool IsAllWrite(IReadOnlyList<ComponentModel> components) => components.All(static component => component.IsWrite);


}
